<?php
require_once __DIR__ . '/../_common.php';api_require_role('admin');
function adminTrxItems(mysqli $conn,int $id):array{$s=$conn->prepare('SELECT d.id_detail,d.id_produk,p.nama_produk,d.jumlah,d.harga_satuan,d.subtotal FROM detail_transaksi d LEFT JOIN produk p ON p.id_produk=d.id_produk WHERE d.id_transaksi=? ORDER BY d.id_detail');$s->bind_param('i',$id);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();return $rows;}
try{api_allow_methods(['GET']);$fields="t.id_transaksi,t.id_user,t.nama_customer,t.id_fo,t.tanggal_masuk,t.tanggal_diproses,t.tanggal_selesai,t.total_harga,t.id_voucher,t.kode_voucher,t.diskon,t.total_bayar,t.metode_pembayaran,t.status_pembayaran,t.status_pesanan,t.bukti_pembayaran,t.alamat_pengiriman,t.catatan,u.nama AS nama_user,a.nama AS nama_fo";$from=' FROM transaksi t LEFT JOIN users u ON u.id_user=t.id_user LEFT JOIN akun a ON a.id_akun=t.id_fo';if(isset($_GET['id_transaksi'])){$id=api_int($_GET['id_transaksi'],'id_transaksi');$s=$conn->prepare('SELECT '.$fields.$from.' WHERE t.id_transaksi=?');$s->bind_param('i',$id);$s->execute();$row=api_one($s);$s->close();if(!$row)throw new OutOfBoundsException('Transaksi tidak ditemukan.');$row['detail']=adminTrxItems($conn,$id);api_reply(200,true,'Detail transaksi berhasil diambil.',$row);}
$sql='SELECT '.$fields.$from.' WHERE 1=1';$types='';$params=[];foreach(['status_pesanan','status_pembayaran','metode_pembayaran'] as $key){if(!empty($_GET[$key])){$sql.=" AND t.{$key}=?";$types.='s';$params[]=trim($_GET[$key]);}}if(!empty($_GET['id_user'])){$sql.=' AND t.id_user=?';$types.='i';$params[]=api_int($_GET['id_user'],'id_user');}$sql.=' ORDER BY t.tanggal_masuk DESC,t.id_transaksi DESC';$s=$conn->prepare($sql);if($types)api_bind($s,$types,$params);$s->execute();$res=$s->get_result();$rows=[];while($row=$res->fetch_assoc()){$row['detail']=adminTrxItems($conn,(int)$row['id_transaksi']);$rows[]=$row;}$s->close();api_reply(200,true,'Daftar transaksi berhasil diambil.',$rows);}catch(Throwable $e){api_db_error($e);}